DETAIL["온다 리프팅"] = [ [ "what", "온다 리프팅이란?", "para", [ "온다는 마이크로파(Coolwaves)를 이용해 지방 세포에 선택적으로 작용하는 장비입니다. 0–7mm 깊이까지 에너지를 전달해 지방 부피를 줄이면서 동시에 피부를 조입니다.", "리프팅 장비로 분류되지만 실제 역할은 \"지방을 줄여 무게를 덜어내는 것\"입니다. 팔자 위 볼살, 심부볼, 이중턱처럼 지방이 원인인 처짐에서 효율이 좋습니다.", "올디테일은 온다를 단독으로 쓰지 않고 울쎄라 · 실리프팅과 역할을 나눠 설계합니다. 지방을 줄이는 것과 당기는 것은 다른 문제이기 때문입니다." ] ], [ "effect", "온다 리프팅 효과", "num", [ [ "볼살 · 심부볼 부피 감소", "팔자 위에 얹힌 지방을 줄여 주름이 겹치는 것을 완화합니다." ], [ "이중턱 정리", "턱밑 지방을 줄여 턱선을 드러냅니다." ], [ "피부 타이트닝", "지방 감소와 동시에 피부가 조여져 처짐을 예방합니다." ], [ "바디 적용 가능", "복부 · 허벅지 · 팔뚝에도 같은 원리로 사용합니다." ], [ "다운타임 거의 없음", "시술 직후 일상 복귀가 가능합니다." ] ] ], [ "who", "온다 리프팅 추천대상", "list", [ "볼살 · 심부볼이 두꺼워 얼굴이 무거워 보이는 분", "이중턱이 지방형인 분", "팔자지우개 볼살형으로 진단된 분", "체중은 정상인데 얼굴이 커 보이는 분", "울쎄라만으로 변화가 부족했던 분" ] ], [ "diff", "올디테일의원의 온다 리프팅 시술 차별점", "num", [ [ "지방 두께를 먼저 측정합니다", "지방이 얇은 부위에 온다를 쓰면 볼이 꺼집니다. 진단에서 구역별 두께를 확인한 뒤 배분합니다." ], [ "울쎄라와 역할을 나눕니다", "온다로 무게를 덜고 울쎄라로 당깁니다. 순서와 간격을 설계합니다." ], [ "앉은 자세에서 구역을 그립니다", "지방을 줄여야 할 구역과 남겨야 할 구역을 펜으로 구분합니다." ], [ "출력을 부위별로 조절합니다", "턱밑과 볼은 다른 출력을 씁니다." ], [ "회차마다 둘레와 두께를 기록합니다", "체감이 아니라 수치로 경과를 확인합니다." ] ] ], [ "mech", "온다 리프팅 작용 원리", "num", [ [ "마이크로파가 지방층에 도달합니다", "물 함량이 낮은 지방 조직에 선택적으로 흡수됩니다." ], [ "지방 세포가 손상됩니다", "열로 세포막이 파괴되고 내용물이 배출됩니다." ], [ "림프로 배출됩니다", "수 주에 걸쳐 대사로 처리됩니다." ], [ "피부가 동시에 조여집니다", "진피 콜라겐도 열을 받아 수축합니다." ] ] ], [ "flow", "온다 리프팅 시술 흐름", "num", [ [ "3D 진단 · 지방 두께 측정", "구역별 지방층을 수치로 확인합니다." ], [ "원장 상담", "줄일 구역과 병행 시술(울쎄라 · 실)을 정합니다." ], [ "앉은 자세 구역 디자인", "줄일 구역과 보존할 구역을 표시합니다." ], [ "연고 마취 · 냉각", "열감을 줄이기 위해 냉각을 병행합니다." ], [ "구역별 조사", "출력을 나누어 진행하며 좌우를 비교합니다." ], [ "4주 후 재평가", "두께 변화를 측정하고 다음 회차를 정합니다." ] ] ], [ "pain", "온다 리프팅 통증", "para", [ "온다는 따뜻한 마사지에 가까운 열감이 특징입니다. 찌르는 통증은 없고, 열이 누적될 때 뜨거움을 느끼는 정도입니다.", "올디테일은 연고 마취와 냉각을 병행하고 핸드피스 이동 속도를 조절해 열이 한 지점에 쌓이지 않게 합니다." ] ], [ "downtime", "온다 리프팅 다운타임", "num", [ [ "당일", "따뜻한 느낌과 가벼운 붉은 기가 있습니다. 메이크업 가능합니다." ], [ "1–2일", "붉은 기가 사라집니다." ], [ "2–4주", "지방이 배출되며 부피 변화가 나타납니다." ], [ "2–3회", "4주 간격으로 누적하며 결과를 평가합니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "시술 후 수분을 충분히 섭취해주세요. 배출에 도움이 됩니다.", "당일 사우나 · 음주는 피해주세요.", "가벼운 활동과 걷기는 배출을 돕습니다.", "식단 관리가 병행되면 결과가 더 명확합니다.", "과한 열감이 하루 이상 지속되면 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 제한됩니다.", "심장 박동기 · 체내 전자 장치가 있는 경우 시술이 불가합니다.", "지방층이 얇은 부위는 시술 대상이 아닙니다.", "시술 부위에 활동성 감염이 있으면 진정 후 진행합니다.", "금속 삽입물이 있는 경우 상담 시 알려주세요." ] ], [ "side", "온다 리프팅 부작용 및 대처방법", "cmp", [ [ "볼 꺼짐", "지방이 얇은 구역에 조사", "진단 기반 구역 설계로 예방합니다. 발생 시 볼륨 보충으로 회복을 돕습니다." ], [ "일시적 붉은 기", "열 자극 반응", "1–2일 내 사라집니다." ], [ "국소 통증 · 압통", "열이 누적된 지점", "수일 내 완화됩니다." ], [ "효과 미미", "처짐이 주 원인인 경우", "진단에서 방향을 조정해 울쎄라 · 실로 설계합니다." ], [ "부기", "림프 배출 과정", "1주 내 완화됩니다. 수분 섭취가 도움이 됩니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "한 번만 받아도 되나요?", "2–3회를 4주 간격으로 진행할 때 부피 변화가 뚜렷합니다. 1회로도 조임은 느낄 수 있습니다." ], [ "볼이 꺼질까 걱정됩니다.", "지방 두께를 먼저 측정해 얇은 구역은 제외합니다. 구역 설계 없이 전체에 조사할 때 생기는 문제입니다." ], [ "울쎄라와 같이 받아도 되나요?", "권장하는 조합입니다. 온다로 무게를 덜고 울쎄라로 당기는 순서로 설계합니다." ], [ "비용은 얼마인가요?", "구역과 회차에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

DETAIL["소프웨이브"] = [ [ "what", "소프웨이브란?", "para", [ "소프웨이브는 중심부 초음파(SUPERB)를 이용해 진피 1.5mm 깊이에 균일한 열을 만드는 리프팅 장비입니다. 울쎄라처럼 깊은 근막을 당기는 대신, 피부 바로 아래를 고르게 가열합니다.", "에너지가 넓고 얕게 퍼지므로 통증이 적고 회복이 빠릅니다. 얇은 피부의 잔주름과 초기 탄력 저하에서 선택하기 좋은 접근입니다.", "처짐이 이미 진행된 경우에는 울쎄라 · 실리프팅으로 방향을 잡고, 소프웨이브는 표면 관리로 병행합니다." ] ], [ "effect", "소프웨이브 효과", "num", [ [ "잔주름 개선", "진피 상부 콜라겐이 재배열되며 얇은 주름이 완화됩니다." ], [ "표면 탄력 회복", "피부가 매끈하게 조여집니다." ], [ "눈가 · 목 적용", "얇은 부위에도 안전하게 사용할 수 있습니다." ], [ "낮은 통증", "에너지가 얕고 넓게 퍼져 자극이 적습니다." ], [ "즉시 일상 복귀", "다운타임이 거의 없습니다." ] ] ], [ "who", "소프웨이브 추천대상", "list", [ "20–30대의 초기 탄력 저하", "얇은 피부의 잔주름", "강한 리프팅이 부담스러운 분", "눈가 · 이마 · 목 집중 관리", "울쎄라 후 표면 관리를 원하는 분" ] ], [ "diff", "올디테일의원의 소프웨이브 시술 차별점", "num", [ [ "처짐과 탄력을 구분해 권합니다", "처짐이 진행된 상태에서 소프웨이브만으로는 변화가 부족합니다. 진단에서 솔직하게 방향을 안내드립니다." ], [ "구역별 조사 횟수를 나눕니다", "탄력이 떨어진 구역에 더 배분합니다." ], [ "눈가 출력을 따로 설정합니다", "피부 두께가 다르므로 얼굴과 같은 세팅을 쓰지 않습니다." ], [ "연고 마취를 기본으로 합니다", "통증이 적은 시술이지만 마취를 생략하지 않습니다." ], [ "병행 순서를 설계합니다", "울쎄라 · 부스터와 간격을 정해 열 자극이 겹치지 않게 합니다." ] ] ], [ "mech", "소프웨이브 작용 원리", "num", [ [ "초음파가 진피 1.5mm에 도달합니다", "표피는 냉각으로 보호됩니다." ], [ "균일한 열 구역이 생깁니다", "점이 아니라 면 형태로 가열됩니다." ], [ "콜라겐이 수축합니다", "즉각적인 조임이 생깁니다." ], [ "1–3개월에 걸쳐 재생됩니다", "새 콜라겐이 생성되며 탄력이 유지됩니다." ] ] ], [ "flow", "소프웨이브 시술 흐름", "num", [ [ "3D 진단", "피부 두께와 탄력 상태를 확인합니다." ], [ "원장 상담", "소프웨이브가 맞는 단계인지 먼저 판정합니다." ], [ "클렌징 · 연고 마취", "부위별 도포 범위를 나눕니다." ], [ "구역별 조사", "탄력이 떨어진 구역에 더 배분합니다." ], [ "진정 관리", "LDM 또는 진정 관리로 마무리합니다." ], [ "3개월 경과 확인", "결과를 평가하고 다음 계획을 정합니다." ] ] ], [ "pain", "소프웨이브 통증", "para", [ "따뜻한 열감이 반복되는 정도이며, 울쎄라보다 통증이 현저히 적습니다. 대부분 마취 없이도 견딜 수 있는 수준입니다.", "다만 올디테일은 연고 마취를 기본으로 합니다. 편안한 상태에서 진행해야 필요한 출력을 충분히 쓸 수 있습니다." ] ], [ "downtime", "소프웨이브 다운타임", "num", [ [ "당일", "가벼운 붉은 기와 열감. 메이크업 · 일상 모두 가능합니다." ], [ "수 시간", "붉은 기가 사라집니다." ], [ "1–3개월", "콜라겐 재생으로 탄력이 개선됩니다." ], [ "연 1회", "유지 관리를 권합니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "당일 사우나 · 격한 운동을 피해주세요.", "보습을 충분히 해주세요.", "자외선 차단제를 사용해주세요.", "특별한 제한은 거의 없습니다." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 제한됩니다.", "시술 부위에 활동성 감염 · 상처가 있으면 진정 후 진행합니다.", "체내 전자 장치가 있는 경우 상담 시 알려주세요.", "켈로이드 체질인 경우 미리 알려주세요." ] ], [ "side", "소프웨이브 부작용 및 대처방법", "cmp", [ [ "일시적 붉은 기", "열 자극 반응", "수 시간 내 사라집니다." ], [ "미세 부기", "진피 부종", "1일 내 완화됩니다." ], [ "압통", "열 응고 반응", "수일 내 사라집니다." ], [ "효과 미미", "처짐이 주 원인인 경우", "진단 단계에서 울쎄라 · 실로 방향을 조정합니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "울쎄라 대신 받아도 되나요?", "다루는 층이 달라 대체 관계가 아닙니다. 처짐이 있으면 울쎄라, 표면 탄력 · 잔주름이면 소프웨이브입니다." ], [ "몇 회 받아야 하나요?", "1회로도 변화가 있고, 탄력 저하가 진행된 경우 2–3회를 나누어 설계합니다." ], [ "임신 중에도 가능한가요?", "임신 · 수유 중에는 진행하지 않습니다." ], [ "비용은 얼마인가요?", "부위와 조사 범위에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

DETAIL["눈가 리프팅"] = [ [ "what", "눈가 리프팅이란?", "para", [ "눈가 리프팅은 눈꼬리 · 눈밑 · 눈꺼풀에 맞춰 저출력 초음파와 고주파를 조합하는 시술입니다. 눈 주위는 얼굴에서 가장 피부가 얇은 부위여서, 얼굴 전체와 같은 세팅을 쓰면 위험합니다.", "눈가만 따로 설계하는 이유는 처짐의 방향도 다르기 때문입니다. 눈꼬리는 바깥 아래로, 눈밑은 앞쪽으로 늘어집니다. 방향에 맞춰 에너지를 배분해야 결과가 자연스럽습니다.", "보호 렌즈를 착용하고 진행하며, 눈가 잔주름은 보톡스 · 아이 리쥬란과 역할을 나눠 함께 설계하는 경우가 많습니다." ] ], [ "effect", "눈가 리프팅 효과", "num", [ [ "눈꼬리 처짐 개선", "눈꼬리 방향을 바로잡아 눈이 또렷해 보입니다." ], [ "눈밑 늘어짐 완화", "얇아진 눈밑 피부가 조여집니다." ], [ "눈가 잔주름 개선", "진피 콜라겐이 재생되며 얇은 주름이 완화됩니다." ], [ "눈꺼풀 무거움 완화", "상안검 피부가 조여져 눈 뜨는 느낌이 가벼워집니다." ], [ "짧은 시술 시간", "20–30분 내 마무리됩니다." ] ] ], [ "who", "눈가 리프팅 추천대상", "list", [ "눈꼬리가 처져 피곤해 보이는 분", "눈밑 피부가 얇아지고 늘어진 분", "눈가 잔주름이 신경 쓰이는 분", "눈꺼풀이 무거워 눈 뜨기가 불편한 분", "수술 없이 눈가만 집중 관리하고 싶은 분" ] ], [ "diff", "올디테일의원의 눈가 리프팅 시술 차별점", "num", [ [ "눈가 전용 세팅을 씁니다", "얼굴 출력을 낮춰 쓰는 것이 아니라 눈가 기준으로 다시 설정합니다." ], [ "처짐 방향을 먼저 판정합니다", "눈꼬리형 · 눈밑형 · 상안검형에 따라 배분이 달라집니다." ], [ "보호 렌즈를 반드시 착용합니다", "안구 보호가 전제입니다. 예외를 두지 않습니다." ], [ "연고 마취를 눈가까지 덮습니다", "눈 주위를 피해 바르면 그 부위가 가장 아픕니다." ], [ "보톡스 · 부스터와 역할을 나눕니다", "근육 요인은 보톡스, 진피 요인은 부스터, 처짐은 리프팅으로 분담합니다." ] ] ], [ "mech", "눈가 리프팅 작용 원리", "num", [ [ "저출력 에너지가 얕은 층에 도달합니다", "눈가 피부 두께에 맞춰 깊이를 제한합니다." ], [ "미세 열 응고점이 생깁니다", "콜라겐이 즉시 수축합니다." ], [ "재생 반응이 시작됩니다", "새로운 콜라겐이 생성됩니다." ], [ "1–3개월에 걸쳐 조여집니다", "눈가 윤곽이 정리됩니다." ] ] ], [ "flow", "눈가 리프팅 시술 흐름", "num", [ [ "눈가 진단", "피부 두께 · 처짐 방향 · 잔주름 상태를 확인합니다." ], [ "원장 상담", "리프팅 단독인지 보톡스 · 부스터 병행인지 정합니다." ], [ "클렌징 · 연고 마취", "눈가를 포함해 충분히 덮고 기다립니다." ], [ "보호 렌즈 착용", "안구를 보호한 뒤 시작합니다." ], [ "방향별 조사", "처짐 방향에 맞춰 에너지를 배분합니다." ], [ "진정 관리 · 안내", "냉각 진정 후 관리 방법을 안내드립니다." ] ] ], [ "pain", "눈가 리프팅 통증", "para", [ "눈가는 신경이 밀집되어 자극에 민감합니다. 다만 저출력으로 진행하므로 울쎄라 같은 깊은 통증은 없고, 따뜻한 자극이 반복되는 정도입니다.", "올디테일은 연고 마취를 눈가까지 충분히 덮고 45분 이상 기다린 뒤 시작합니다. 눈 주위를 피해 바르는 경우 그 부위가 가장 아프기 때문입니다." ] ], [ "downtime", "눈가 리프팅 다운타임", "num", [ [ "당일", "가벼운 붉은 기와 부기. 메이크업 가능합니다." ], [ "1일", "붉은 기가 사라집니다." ], [ "1–3개월", "조임과 잔주름 개선이 나타납니다." ], [ "연 1–2회", "유지 관리를 권합니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "시술 당일 눈을 비비지 마세요.", "콘택트렌즈는 당일 착용을 피해주세요.", "눈가 보습을 충분히 해주세요.", "자외선 차단과 선글라스를 활용해주세요.", "부기가 3일 이상이면 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "안구 질환 · 최근 눈 수술 이력이 있으면 상담 시 알려주세요.", "임신 · 수유 중에는 시술이 제한됩니다.", "눈가에 필러가 있는 경우 위치를 확인한 뒤 배분합니다.", "보호 렌즈 착용 없이는 진행하지 않습니다.", "활동성 감염 · 결막염이 있으면 회복 후 진행합니다." ] ], [ "side", "눈가 리프팅 부작용 및 대처방법", "cmp", [ [ "부기", "얇은 피부의 부종 반응", "1–2일 내 완화됩니다. 냉찜질이 도움이 됩니다." ], [ "붉은 기", "열 자극 반응", "수 시간–1일 내 사라집니다." ], [ "일시적 뻐근함", "열 응고 회복 반응", "수일 내 사라집니다." ], [ "눈물 흘림", "자극에 대한 일시적 반응", "시술 중·직후에 국한되며 곧 사라집니다." ], [ "효과 미미", "피부 처짐보다 지방 · 근육 요인이 큰 경우", "진단에서 방향을 조정하거나 수술 상담을 안내합니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "눈에 위험하지 않나요?", "보호 렌즈를 착용하고 안구를 피해 얕은 깊이로만 조사합니다. 에너지가 안구에 도달하지 않도록 설계합니다." ], [ "눈꺼풀 처짐도 개선되나요?", "피부 처짐이 원인이면 도움이 됩니다. 지방이나 근육 문제라면 수술이 필요할 수 있어 진단에서 구분합니다." ], [ "보톡스와 같이 받아도 되나요?", "가능합니다. 근육 요인은 보톡스, 처짐은 리프팅으로 역할을 나눕니다." ], [ "비용은 얼마인가요?", "조합과 범위에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

DETAIL["실리프팅"] = [ [ "what", "실리프팅이란?", "para", [ "실리프팅은 몸에서 흡수되는 실(PDO · PCL)을 피하층에 삽입해 처진 조직을 물리적으로 당겨 고정하는 시술입니다. 에너지 리프팅이 조직을 수축시키는 것과 달리, 실리프팅은 위치를 직접 옮깁니다.", "그래서 결과가 즉각적입니다. 다만 잘못 설계하면 딤플(피부 함몰), 비대칭, 당김 자국이 남습니다. 실의 개수가 아니라 진입 방향과 고정 지점이 결과를 정합니다.", "올디테일은 실리프팅에 리버스 디자인을 적용합니다. 진입 방향을 달리해 당기는 힘이 표면에 몰리지 않게 하고, 딤플 위험을 줄입니다." ] ], [ "effect", "실리프팅 효과", "num", [ [ "즉각적인 당김", "시술 직후부터 윤곽 변화가 보입니다." ], [ "심부볼 상방 고정", "내려앉은 볼살을 위로 올려 고정합니다." ], [ "팔자 · 마리오네트 완화", "주름 위에 얹힌 볼살이 올라가며 주름이 얕아집니다." ], [ "턱선 정리", "늘어진 하안면을 당겨 경계를 만듭니다." ], [ "콜라겐 생성", "실 주변에서 콜라겐이 생성되어 유지에 도움이 됩니다." ] ] ], [ "who", "실리프팅 추천대상", "list", [ "울쎄라 · 써마지로 변화가 부족했던 분", "심부볼 · 팔자 위 볼살이 내려앉은 분", "즉각적인 윤곽 변화가 필요한 분", "수술은 부담스럽지만 확실한 당김을 원하는 분", "처짐형 팔자로 진단된 분" ] ], [ "diff", "올디테일의원의 실리프팅 시술 차별점", "num", [ [ "리버스 디자인으로 딤플을 줄입니다", "진입 방향과 고정 지점을 달리해 당기는 힘이 표면 한 점에 몰리지 않게 합니다." ], [ "앉은 자세에서 벡터를 그립니다", "당길 방향을 화살표로 표시하고 표정을 움직여 확인합니다. 누운 상태의 설계는 실제와 다릅니다." ], [ "실 개수보다 배치를 설계합니다", "많이 넣는 것이 아니라 필요한 벡터에 필요한 개수만 넣습니다." ], [ "국소 마취를 충분히 합니다", "진입점과 실 경로를 따라 마취합니다." ], [ "에너지 리프팅과 순서를 정합니다", "울쎄라로 조직을 조인 뒤 실로 고정하는 순서가 일반적입니다." ] ] ], [ "ba", "비포앤애프터", "ba", [ [ "case-sag-before.jpg", "case-sag-after.jpg", "처짐형 팔자 — 리버스 디자인 실리프팅", "50% 42%" ] ] ], [ "mech", "실리프팅 작용 원리", "num", [ [ "캐뉼라로 실을 삽입합니다", "피하층의 설계한 경로를 따라 진입합니다." ], [ "돌기가 조직을 잡습니다", "실의 돌기(코그)가 처진 조직에 걸립니다." ], [ "상방으로 당겨 고정합니다", "설계한 벡터 방향으로 위치를 옮깁니다." ], [ "콜라겐이 생성됩니다", "실이 흡수되는 동안 주변에 콜라겐이 형성되어 유지에 기여합니다." ] ] ], [ "flow", "실리프팅 시술 흐름", "num", [ [ "3D 진단", "처짐 방향과 지방 두께를 확인합니다." ], [ "원장 상담", "벡터와 실 종류 · 개수를 정합니다." ], [ "앉은 자세 벡터 디자인", "당길 방향과 진입점을 표시합니다." ], [ "연고 + 국소 마취", "진입점과 경로를 따라 충분히 마취합니다." ], [ "실 삽입 · 고정", "좌우를 번갈아 진행하며 대칭을 확인합니다." ], [ "2주 후 경과 확인", "부기가 빠진 상태에서 대칭과 당김을 확인합니다." ] ] ], [ "pain", "실리프팅 통증", "para", [ "실리프팅은 국소 마취를 충분히 하면 시술 중 통증이 크지 않습니다. 오히려 시술 후 며칠간의 당김과 뻐근함이 더 기억에 남습니다.", "올디테일은 진입점과 실 경로를 따라 마취를 배분하고, 마취가 충분히 오른 것을 확인한 뒤 시작합니다. 시술 후 관리 방법도 함께 안내드립니다." ] ], [ "downtime", "실리프팅 다운타임", "num", [ [ "당일", "진입점에 미세한 자국과 부기가 있습니다." ], [ "2–3일", "부기가 가장 심한 시기입니다. 당김과 뻐근함이 있습니다." ], [ "1주", "멍이 있다면 옅어지고 부기가 줄어듭니다." ], [ "2–4주", "자연스러운 상태로 자리를 잡습니다. 2주 시점에 경과를 확인합니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "2주간 크게 입을 벌리거나 과한 표정을 피해주세요.", "2주간 시술 부위 마사지 · 얼굴 눌러 자는 자세를 피해주세요.", "1주간 사우나 · 격한 운동 · 음주를 피해주세요.", "진입점은 물이 닿지 않게 하루 정도 관리해주세요.", "한쪽만 심한 통증 · 함몰 · 발열이 있으면 즉시 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 제한됩니다.", "항응고제 복용 중이거나 출혈 질환이 있으면 멍이 크게 생길 수 있습니다.", "시술 부위에 활동성 감염이 있으면 진정 후 진행합니다.", "켈로이드 체질인 경우 상담 시 반드시 알려주세요.", "정품 실만 사용하며 개봉은 환자분 앞에서 진행합니다." ] ], [ "side", "실리프팅 부작용 및 대처방법", "cmp", [ [ "딤플 (함몰)", "당기는 힘이 표면 한 점에 집중", "리버스 디자인으로 예방합니다. 발생 시 대부분 수 주 내 완화되며 필요 시 처치합니다." ], [ "비대칭", "좌우 당김 정도 차이", "2주 시점에 평가하고 필요하면 보완합니다." ], [ "멍 · 부기", "캐뉼라 진입에 따른 반응", "1–2주 내 완화됩니다." ], [ "실 만져짐", "피하 얕은 층에 위치", "대부분 흡수되며 사라집니다. 지속되면 내원해주세요." ], [ "감염", "진입점 관리 미흡", "드물지만 발열 · 통증 증가 시 즉시 내원해주세요. 항생제로 대응합니다." ], [ "당김 · 뻐근함", "조직이 이동한 정상 반응", "2주에 걸쳐 완화됩니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "딤플이 생기지 않나요?", "진입 방향과 고정 지점을 달리한 리버스 디자인으로 진행합니다. 설계 없이 당기면 딤플 위험이 커집니다." ], [ "실은 몇 개가 적당한가요?", "개수가 아니라 벡터가 중요합니다. 필요한 방향에 필요한 개수만 넣습니다. 진단 후 설계해 안내드립니다." ], [ "얼마나 유지되나요?", "8–12개월 전후이며, 울쎄라와 병행하면 유지 기간이 길어지는 편입니다." ], [ "실이 녹으면 더 처지나요?", "실이 흡수되는 동안 생성된 콜라겐이 남습니다. 시술 전보다 더 처지지는 않습니다." ], [ "비용은 얼마인가요?", "실 종류와 개수 · 벡터 설계에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

DETAIL["이중턱 윤곽"] = [ [ "what", "이중턱 윤곽이란?", "para", [ "이중턱은 하나의 문제가 아닙니다. 턱밑 지방이 많은 지방형, 피부와 근육이 늘어난 처짐형, 그리고 두 가지가 섞인 혼합형으로 나뉩니다. 유형을 구분하지 않으면 시술을 받아도 변화가 없습니다.", "지방형에 리프팅만 하면 지방이 그대로 남고, 처짐형에 지방분해만 하면 피부가 더 늘어져 보입니다. 올디테일은 진단으로 유형과 비중을 먼저 나눕니다.", "여기에 턱 구조(후퇴한 턱 · 작은 턱)까지 함께 봅니다. 구조 문제라면 필러로 턱끝을 보강하는 것이 더 효율적인 경우도 있습니다." ] ], [ "effect", "이중턱 윤곽 효과", "num", [ [ "턱선 재형성", "턱과 목의 경계가 다시 드러납니다." ], [ "측면 라인 개선", "옆에서 볼 때 턱선이 정리됩니다." ], [ "얼굴 크기 인상 개선", "정면 사진에서 하안면이 좁아 보입니다." ], [ "목 · 턱 경계 정리", "고개를 숙일 때 접히던 턱살이 줄어듭니다." ], [ "유형별 맞춤 조합", "지방 · 처짐 · 구조 비중에 따라 시술을 배분합니다." ] ] ], [ "who", "이중턱 윤곽 추천대상", "list", [ "옆에서 볼 때 턱과 목의 경계가 없는 분", "고개를 숙이면 턱살이 접히는 분", "체중과 무관하게 턱밑이 두꺼운 분", "사진에서 얼굴이 커 보이는 분", "이중턱 시술을 받았지만 변화가 없었던 분" ] ], [ "compare", "이중턱 유형별 접근", "cmp4", { "highlight": null, "head": [ "구분", "지방형", "처짐형", "혼합형" ], "rows": [ [ "주된 원인", "턱밑 지방 축적", "피부 · 근육 탄력 저하", "지방 + 처짐" ], [ "1차 접근", "지방분해 주사 · 온다", "울쎄라 · 실리프팅", "온다 → 울쎄라 순서" ], [ "보조 접근", "바디온다 · 식단 관리", "써마지 · 실", "턱끝 필러로 구조 보강" ], [ "회차", "4–6회 · 2주 간격", "1회 후 3개월 평가", "2–3회 조합 설계" ], [ "체감 시점", "4–8주", "2–3개월", "4주부터 단계적으로" ] ] } ], [ "diff", "올디테일의원의 이중턱 윤곽 시술 차별점", "num", [ [ "유형을 먼저 판정합니다", "지방 · 처짐 · 구조의 비중을 수치로 나눈 뒤 시술을 정합니다." ], [ "지방과 탄력을 같은 계획에 둡니다", "지방만 빼면 피부가 남아 더 처집니다. 빠지는 속도에 맞춰 탄력 관리를 병행합니다." ], [ "턱 구조까지 함께 봅니다", "후퇴한 턱이라면 아무리 지방을 빼도 라인이 생기지 않습니다. 필요 시 턱끝 보강을 제안합니다." ], [ "앉은 자세 · 측면에서 디자인합니다", "이중턱은 측면이 기준입니다. 정면만 보고 설계하지 않습니다." ], [ "회차마다 측정하고 기록합니다", "체감이 아니라 둘레 · 두께 변화를 수치로 확인합니다." ] ] ], [ "mech", "이중턱 윤곽 작용 원리", "num", [ [ "지방을 줄입니다", "지방분해 주사 · 온다로 턱밑 지방 부피를 감소시킵니다." ], [ "근막을 조입니다", "울쎄라가 4.5mm 층을 수축시켜 늘어난 구조를 당깁니다." ], [ "피부를 고정합니다", "필요 시 실리프팅으로 처진 조직을 상방 고정합니다." ], [ "구조를 보강합니다", "턱끝이 후퇴한 경우 필러로 측면 라인의 기준점을 만듭니다." ] ] ], [ "flow", "이중턱 윤곽 시술 흐름", "num", [ [ "3D 진단 · 측면 촬영", "지방 두께 · 탄력 · 턱 구조를 측정합니다." ], [ "원장 상담", "유형과 비중을 판정하고 조합 · 회차를 설계합니다." ], [ "측면 기준 디자인", "앉은 자세에서 측면을 보며 구역을 표시합니다." ], [ "마취", "주사는 연고 + 냉각, 울쎄라는 신경 마취를 더합니다." ], [ "단계별 시술", "지방 → 탄력 순서로 회차를 나누어 진행합니다." ], [ "회차별 측정 · 재평가", "둘레와 두께를 기록하고 계획을 조정합니다." ] ] ], [ "pain", "이중턱 윤곽 통증", "para", [ "조합에 따라 통증이 다릅니다. 지방분해 주사는 찌르는 자극과 이후의 뻐근함, 울쎄라는 뼈에 가까운 깊은 통증, 실리프팅은 시술 후 당김이 특징입니다.", "올디테일은 각 시술마다 마취를 다르게 설계합니다. 주사는 연고 + 냉각, 울쎄라는 신경 마취 추가, 실은 국소 마취를 충분히 배분합니다." ] ], [ "downtime", "이중턱 윤곽 다운타임", "num", [ [ "당일", "부기와 멍이 있을 수 있습니다. 조합에 따라 다릅니다." ], [ "3–5일", "부기가 가장 심한 시기이며 이후 빠르게 줄어듭니다." ], [ "1–2주", "멍이 사라지고 라인이 드러나기 시작합니다." ], [ "2–3개월", "탄력 시술의 결과가 나타나며 최종 평가를 합니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "시술 후 1주간 사우나 · 격한 운동 · 음주를 피해주세요.", "수분을 충분히 섭취해주세요. 지방 배출에 도움이 됩니다.", "실리프팅을 병행한 경우 2주간 과한 표정과 마사지를 피해주세요.", "식단 관리가 병행되면 결과가 더 명확합니다.", "한쪽만 심한 통증이나 발열이 있으면 즉시 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 제한됩니다.", "갑상선 질환 · 목 부위 수술 이력이 있으면 상담 시 알려주세요.", "항응고제 복용 중이면 멍이 크게 생길 수 있습니다.", "시술 부위에 활동성 감염이 있으면 진정 후 진행합니다.", "모든 조합은 정품 · 정량을 원칙으로 합니다." ] ], [ "side", "이중턱 윤곽 부작용 및 대처방법", "cmp", [ [ "부기 · 멍", "주사 · 캐뉼라 진입 반응", "1–2주 내 완화됩니다. 냉찜질이 도움이 됩니다." ], [ "울퉁불퉁함", "지방이 불균일하게 감소", "회차를 나누어 균일하게 접근하고, 발생 시 다음 회차에서 보정합니다." ], [ "피부 늘어짐", "지방만 급격히 감소", "탄력 관리를 같은 계획에 포함해 예방합니다." ], [ "일시적 감각 저하", "신경 주변 자극", "대부분 수 주 내 회복됩니다." ], [ "효과 미미", "턱 구조가 주 원인인 경우", "진단에서 구조 문제를 먼저 확인하고 방향을 조정합니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "지방만 빼면 되지 않나요?", "지방만 빼면 그 자리를 덮던 피부가 남아 더 처져 보일 수 있습니다. 탄력 관리를 같은 계획에 넣는 이유입니다." ], [ "몇 회 받아야 하나요?", "유형에 따라 다릅니다. 지방형은 4–6회, 처짐형은 1회 후 3개월 평가, 혼합형은 2–3회 조합으로 설계합니다." ], [ "살이 빠지면 저절로 없어지나요?", "체중 감소로 개선되는 경우도 있지만, 턱 구조나 탄력이 원인이면 체중만으로는 달라지지 않습니다." ], [ "비용은 얼마인가요?", "조합과 회차에 따라 크게 달라지므로 진단과 상담 후 안내드립니다." ] ] ] ];

