DETAIL["주름 보톡스"] = [ [ "what", "주름 보톡스 시술 소개", "para", [ "보톡스는 보툴리눔 톡신이 신경과 근육 사이의 신호 전달을 차단해, 표정근의 과한 수축을 줄이는 시술입니다. 주름을 채우는 것이 아니라 주름을 만드는 움직임을 줄입니다.", "그래서 표정을 지을 때 생기는 주름(동적 주름)에 가장 효과적입니다. 무표정에도 깊게 남은 주름은 필러 · 부스터와 역할을 나눠야 합니다.", "올디테일은 \"표정을 없애는 보톡스\"를 만들지 않습니다. 부위별로 용량과 깊이를 나누어, 주름은 줄이고 표정은 남기는 것을 기준으로 삼습니다." ] ], [ "effect", "주름 보톡스 효과", "num", [ [ "이마 가로 주름 완화", "이마근의 과한 수축을 줄여 선이 얕아집니다." ], [ "미간 세로 주름 개선", "인상을 쓸 때 생기는 주름이 완화되어 부드러운 인상이 됩니다." ], [ "눈가 잔주름 개선", "웃을 때 퍼지는 눈꼬리 주름이 줄어듭니다." ], [ "주름 고정 예방", "반복 수축으로 주름이 고정되는 것을 늦춥니다." ], [ "짧은 시술 · 즉시 일상", "10분 내 끝나고 바로 일상 복귀가 가능합니다." ] ] ], [ "who", "주름 보톡스 추천대상", "list", [ "표정을 지을 때 주름이 두드러지는 분", "이마 · 미간 · 눈가 주름이 신경 쓰이는 분", "인상을 쓴 것처럼 보인다는 말을 듣는 분", "주름이 고정되기 전에 예방하고 싶은 분", "자연스러운 표정을 유지하고 싶은 분" ] ], [ "diff", "올디테일의원의 주름 보톡스 시술 차별점", "num", [ [ "눈꺼풀 처짐을 먼저 확인합니다", "눈을 뜨기 위해 이마근을 쓰는 분에게 이마 보톡스를 과하게 쓰면 눈이 무거워집니다. 보상 습관을 확인한 뒤 용량을 정합니다." ], [ "부위별 용량을 나눕니다", "정해진 용량을 균일하게 넣지 않습니다. 근육 힘과 주름 방향을 보고 지점마다 다르게 배분합니다." ], [ "표정을 움직여보며 설계합니다", "무표정 상태의 주름이 아니라 실제 표정에서 생기는 선을 기준으로 지점을 정합니다." ], [ "정품 · 개봉 확인을 원칙으로 합니다", "제품과 용량을 환자분 앞에서 확인하실 수 있습니다." ], [ "2주 후 경과를 확인합니다", "효과가 자리 잡는 시점에 좌우와 잔여 움직임을 점검하고 필요 시 미세 보정합니다." ] ] ], [ "mech", "주름 보톡스 작용 원리", "num", [ [ "신경 말단에 작용합니다", "아세틸콜린 분비를 억제해 신호 전달을 차단합니다." ], [ "근육 수축이 줄어듭니다", "3–7일에 걸쳐 서서히 힘이 빠집니다." ], [ "주름이 얕아집니다", "반복 접힘이 줄어들며 피부가 펴집니다." ], [ "3–4개월 후 회복됩니다", "신경 말단이 재생되며 서서히 원래 상태로 돌아옵니다." ] ] ], [ "flow", "주름 보톡스 시술 흐름", "num", [ [ "진단 · 표정 확인", "표정을 움직여보며 근육 힘과 주름 방향을 확인합니다." ], [ "원장 상담", "부위별 용량과 잔여 움직임의 정도를 함께 정합니다." ], [ "클렌징 · 냉각", "필요 시 연고 마취를 병행합니다." ], [ "지점별 주입", "근육 힘에 따라 지점마다 용량을 나누어 주입합니다." ], [ "주의사항 안내", "4시간 동안 눕지 않기 등 당일 주의사항을 안내드립니다." ], [ "2주 후 경과 확인", "좌우와 잔여 움직임을 점검하고 필요 시 보정합니다." ] ] ], [ "pain", "주름 보톡스 통증", "para", [ "매우 얇은 주사 바늘을 사용해 자극이 짧고 가볍습니다. 대부분 마취 없이 진행 가능한 수준입니다.", "통증에 예민한 분께는 연고 마취와 냉각을 병행합니다. 시술 시간이 10분 내외이므로 마취 대기 시간이 부담되지 않는 범위에서 조절합니다." ] ], [ "downtime", "주름 보톡스 다운타임", "num", [ [ "당일", "주입 자리에 미세한 붉은 점이 있을 수 있습니다. 일상 복귀 가능합니다." ], [ "3–7일", "서서히 근육 힘이 빠지며 주름이 얕아집니다." ], [ "2주", "효과가 완전히 자리 잡습니다. 경과를 확인합니다." ], [ "3–4개월", "서서히 회복됩니다. 반복 시 유지 기간이 길어지는 경향이 있습니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "시술 후 4시간 동안 눕지 마세요. 약물이 이동할 수 있습니다.", "당일 사우나 · 격한 운동 · 음주를 피해주세요.", "시술 부위를 문지르거나 마사지하지 마세요.", "당일 마스크팩 · 강한 클렌징은 피해주세요.", "눈꺼풀이 무겁거나 좌우 차이가 느껴지면 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 불가합니다.", "근신경 질환(근무력증 등)이 있는 경우 시술이 제한됩니다.", "아미노글리코사이드계 항생제를 복용 중이면 알려주세요.", "이전 보톡스에 내성 · 이상 반응이 있었다면 상담 시 알려주세요.", "정품만 사용하며 개봉은 환자분 앞에서 진행합니다." ] ], [ "side", "주름 보톡스 부작용 및 대처방법", "cmp", [ [ "눈꺼풀 처짐", "약물이 눈꺼풀 근육으로 확산", "눈꺼풀 처짐 여부를 먼저 확인하고 용량 · 위치를 조절해 예방합니다. 발생 시 수 주 내 회복됩니다." ], [ "이마 무거움", "이마근 보상 작용을 과하게 차단", "용량을 나누어 예방합니다. 대부분 4–6주 내 완화됩니다." ], [ "좌우 비대칭", "근육 힘 차이", "2주 시점에 확인해 미세 보정합니다." ], [ "미세 멍", "주입 시 혈관 자극", "1주 내 사라집니다." ], [ "두통", "근육 이완 과정의 일시적 반응", "수일 내 사라집니다." ], [ "효과 미미", "내성 또는 용량 부족", "제품 변경 또는 용량 재설계를 상담합니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "표정이 어색해지지 않나요?", "부위별로 용량을 나누고 잔여 움직임을 남기는 것을 기준으로 설계합니다. 상담에서 원하는 정도를 함께 정합니다." ], [ "얼마나 유지되나요?", "보통 3–4개월이며, 반복 시 유지 기간이 길어지는 경향이 있습니다." ], [ "맞을수록 내성이 생기나요?", "드물지만 항체 형성으로 반응이 떨어질 수 있습니다. 필요 이상으로 자주 맞지 않도록 간격을 설계합니다." ], [ "무표정에도 있는 주름에 효과가 있나요?", "고정된 깊은 주름은 보톡스만으로 부족합니다. 필러 · 부스터와 역할을 나눠 함께 설계합니다." ], [ "비용은 얼마인가요?", "부위와 용량에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

DETAIL["사각턱"] = [ [ "what", "사각턱이란?", "para", [ "사각턱 보톡스는 교근(깨물근)의 수축을 줄여 근육 부피를 감소시키는 시술입니다. 뼈를 깎는 것이 아니라 근육의 두께를 줄여 하안면 폭을 좁힙니다.", "따라서 근육이 발달한 경우에 효과적이고, 뼈 자체가 넓은 경우에는 변화가 제한적입니다. 진단에서 근육형 · 골격형을 구분하는 것이 먼저입니다.", "이갈이 · 턱 뭉침이 있는 분은 증상 완화 효과를 함께 얻는 경우가 많습니다." ] ], [ "effect", "사각턱 효과", "num", [ [ "하안면 폭 감소", "근육 부피가 줄어 얼굴이 좁아 보입니다." ], [ "V라인 형성", "턱선이 부드러운 곡선으로 정리됩니다." ], [ "이갈이 완화", "교근 힘이 줄어 이갈이와 턱 통증이 완화됩니다." ], [ "턱 뭉침 개선", "씹을 때 딱딱하게 뭉치던 느낌이 줄어듭니다." ], [ "반복 시 누적 효과", "주기적으로 관리하면 근육 부피 감소가 유지되는 편입니다." ] ] ], [ "who", "사각턱 추천대상", "list", [ "이를 꽉 물면 턱 근육이 단단하게 튀어나오는 분", "정면에서 하안면이 넓어 보이는 분", "이갈이 · 턱 통증이 있는 분", "V라인을 원하지만 수술은 부담스러운 분", "체중과 무관하게 얼굴이 커 보이는 분" ] ], [ "diff", "올디테일의원의 사각턱 시술 차별점", "num", [ [ "근육형 · 골격형을 구분합니다", "뼈가 원인이면 보톡스로 변화가 제한적입니다. 진단에서 솔직하게 안내드립니다." ], [ "좌우 두께를 측정해 용량을 나눕니다", "대부분 좌우 근육 두께가 다릅니다. 같은 용량을 넣으면 비대칭이 남습니다." ], [ "주입 깊이를 근육층까지 확인합니다", "얕게 들어가면 효과가 떨어지고 표정근에 영향을 줄 수 있습니다." ], [ "볼 꺼짐 위험을 미리 확인합니다", "근육이 줄면 볼이 꺼져 보일 수 있는 얼굴형이 있습니다. 필요 시 볼륨 계획을 함께 세웁니다." ], [ "2주 후 경과를 확인합니다", "효과가 나타나는 시점에 좌우를 점검하고 필요 시 보정합니다." ] ] ], [ "mech", "사각턱 작용 원리", "num", [ [ "교근에 약물이 주입됩니다", "근육층 깊이까지 정확히 도달해야 합니다." ], [ "수축이 줄어듭니다", "2–4주에 걸쳐 근육 사용이 감소합니다." ], [ "근육 부피가 감소합니다", "사용이 줄어든 근육이 위축되며 두께가 줄어듭니다." ], [ "4–6개월 후 회복됩니다", "반복 시 감소 상태가 더 오래 유지되는 편입니다." ] ] ], [ "flow", "사각턱 시술 흐름", "num", [ [ "진단 · 근육 두께 측정", "이를 물었을 때의 근육 발달 정도와 좌우 차이를 확인합니다." ], [ "원장 상담", "근육형 비중과 예상 변화, 볼륨 계획을 함께 정합니다." ], [ "클렌징 · 냉각", "필요 시 연고 마취를 병행합니다." ], [ "깊이별 주입", "근육층에 도달하도록 좌우 용량을 나누어 주입합니다." ], [ "주의사항 안내", "당일 주의사항과 경과 시점을 안내드립니다." ], [ "2주 후 경과 확인", "좌우 대칭과 변화 정도를 점검합니다." ] ] ], [ "pain", "사각턱 통증", "para", [ "주입 지점이 적고 바늘이 얇아 자극이 짧습니다. 다만 근육층까지 들어가므로 순간적인 묵직한 느낌이 있을 수 있습니다.", "통증에 예민한 분께는 냉각과 연고 마취를 병행합니다." ] ], [ "downtime", "사각턱 다운타임", "num", [ [ "당일", "미세한 붉은 점. 일상 복귀 가능합니다." ], [ "1주", "씹을 때 힘이 약해지는 느낌이 시작됩니다." ], [ "2–4주", "근육 부피 감소가 나타나며 라인이 정리됩니다." ], [ "4–6개월", "서서히 회복됩니다. 반복 관리 시점을 안내드립니다." ] ] ], [ "care", "회복 관리 가이드", "list", [ "시술 후 4시간 동안 눕지 마세요.", "당일 사우나 · 격한 운동 · 음주를 피해주세요.", "질긴 음식 · 껌을 줄이면 효과 유지에 도움이 됩니다.", "턱을 세게 마사지하지 마세요.", "씹기가 과도하게 불편하거나 좌우 차이가 크면 내원해주세요." ] ], [ "safety", "주의사항 및 안전성", "list", [ "임신 · 수유 중에는 시술이 불가합니다.", "근신경 질환이 있는 경우 시술이 제한됩니다.", "턱관절 질환이 있으면 상담 시 알려주세요.", "과도한 반복은 볼 꺼짐 · 씹기 불편을 유발할 수 있어 간격을 설계합니다.", "정품만 사용하며 개봉은 환자분 앞에서 진행합니다." ] ], [ "side", "사각턱 부작용 및 대처방법", "cmp", [ [ "씹기 불편", "교근 힘 감소의 정상 반응", "2–4주 내 적응됩니다. 심하면 다음 회차 용량을 조절합니다." ], [ "볼 꺼짐", "근육 부피 감소로 지지력 저하", "얼굴형을 먼저 확인해 예방하고, 필요 시 볼륨 보충을 병행합니다." ], [ "좌우 비대칭", "근육 두께 차이", "2주 시점에 확인해 보정합니다." ], [ "미소 시 어색함", "약물이 인접 근육으로 확산", "주입 깊이와 위치를 정확히 해 예방합니다. 수 주 내 완화됩니다." ], [ "미세 멍", "혈관 자극", "1주 내 사라집니다." ] ] ], [ "faq", "자주 묻는 질문", "faq", [ [ "뼈가 넓은 것도 개선되나요?", "골격이 원인이면 보톡스로는 제한적입니다. 진단에서 근육형 비중을 확인해 예상 변화를 안내드립니다." ], [ "얼마나 유지되나요?", "4–6개월이며, 반복 관리 시 근육 부피 감소가 더 오래 유지되는 편입니다." ], [ "볼이 꺼질까 걱정됩니다.", "볼 지방이 적은 얼굴형은 근육이 줄면 꺼져 보일 수 있습니다. 진단에서 미리 확인하고 볼륨 계획을 함께 세웁니다." ], [ "이갈이에도 도움이 되나요?", "교근 힘이 줄어 이갈이와 턱 통증이 완화되는 경우가 많습니다." ], [ "비용은 얼마인가요?", "용량에 따라 달라지므로 상담 후 안내드립니다." ] ] ] ];

